<?php
declare(strict_types=1);
require_once __DIR__.'/accounting_ledger.php';
require_once __DIR__.'/financial_event_guard.php';
final class ClubExpenseException extends RuntimeException {}
function clubExpenseOne(PDO $p,string $table,int $id):array {
 if(!in_array($table,['club_expense_cases','club_expense_claims','club_expense_advances'],true))throw new LogicException('Unknown expense table.');
 $q=$p->prepare('SELECT * FROM '.$table.' WHERE id=?');$q->execute([$id]);$r=$q->fetch(PDO::FETCH_ASSOC);if(!$r)throw new ClubExpenseException('Záznam nebyl nalezen.');return $r;
}
function clubExpenseDate(string $s):string {$d=DateTimeImmutable::createFromFormat('!Y-m-d',$s);if(!$d||$d->format('Y-m-d')!==$s)throw new ClubExpenseException('Zadejte platné datum.');return $s;}
function clubExpenseMinor(mixed $n,bool $zero=false):int {if(!is_int($n)||$n<($zero?0:1)||$n>1000000000000)throw new ClubExpenseException('Neplatná částka v haléřích.');return $n;}
function clubExpensePerson(PDO $p,string $kind,int $id,string $label,bool $external=true):array {
 if($kind==='supplier'&&$external)return ['kind'=>$kind,'id'=>null,'label'=>accountingLedgerText($label,160)];
 $table=match($kind){'trainer'=>'treneri','person'=>'sportovci',default=>throw new ClubExpenseException('Vyberte konkrétní osobu nebo dodavatele.')};
 $q=$p->prepare('SELECT id FROM '.$table.' WHERE id=?');$q->execute([$id]);if(!$q->fetchColumn())throw new ClubExpenseException('Osoba nebyla nalezena.');
 return ['kind'=>$kind,'id'=>$id,'label'=>accountingLedgerText($label,160)];
}
function clubExpenseWrite(PDO $p,int $actor,string $reason,bool $confirmed,callable $fn):mixed {
 $reason=accountingLedgerAudit($actor,$reason,$confirmed);return accountingLedgerTransaction($p,function()use($p,$actor,$reason,$fn){accountingLedgerActor($p,$actor);return $fn($reason);});
}
function clubExpenseEvent(PDO $p,string $type,int $id,string $event,int $actor,string $reason,string $evidence=''):void {$p->prepare('INSERT INTO club_expense_events(entity_type,entity_id,event_type,reason,evidence,actor_trainer_id) VALUES(?,?,?,?,?,?)')->execute([$type,$id,$event,$reason,$evidence,$actor]);}
function clubExpenseOpenCase(PDO $p,?int $id):void {if(!$id)return;$c=clubExpenseOne($p,'club_expense_cases',$id);if($c['state']!=='open')throw new ClubExpenseException('Finanční případ je uzavřený; vyžaduje samostatnou opravnou verzi.');if($c['legacy_event_id'])financialEventAssertOpen(financialEventLock($p,(int)$c['legacy_event_id']));}
function clubExpenseCreateCase(PDO $p,array $in,int $actor,string $reason,bool $confirmed):array {
 return clubExpenseWrite($p,$actor,$reason,$confirmed,function($reason)use($p,$in,$actor){
  $request=(string)($in['request_key']??'');$identity=['title'=>(string)($in['title']??''),'legacy_event_id'=>(int)($in['legacy_event_id']??0),'club_event_id'=>(int)($in['club_event_id']??0),'leader_trainer_id'=>(int)($in['leader_trainer_id']??0),'due_on'=>(string)($in['due_on']??''),'evidence'=>(string)($in['evidence']??'')];$fingerprint=hash('sha256',json_encode($identity,JSON_THROW_ON_ERROR));
  if($request!==''){accountingLedgerText($request,100);foreach($p->query("SELECT entity_id,evidence FROM club_expense_events WHERE entity_type='case' AND event_type='created'")->fetchAll(PDO::FETCH_ASSOC) as $prior){$meta=json_decode($prior['evidence'],true);if(is_array($meta)&&($meta['request_key']??'')===$request){if(!hash_equals((string)$meta['fingerprint'],$fingerprint))throw new ClubExpenseException('Klíč případu již patří jinému zadání.');return clubExpenseOne($p,'club_expense_cases',(int)$prior['entity_id']);}}}
  $legacy=(int)($in['legacy_event_id']??0);if($legacy){financialEventAssertOpen(financialEventLock($p,$legacy));$q=$p->prepare('SELECT * FROM club_expense_cases WHERE legacy_event_id=?');$q->execute([$legacy]);if($q->fetch())throw new ClubExpenseException('Finanční akce již má navázaný případ.');}
  $club=(int)($in['club_event_id']??0);if($club){$q=$p->prepare('SELECT id FROM club_events WHERE id=?');$q->execute([$club]);if(!$q->fetchColumn())throw new ClubExpenseException('Sportovní akce nebyla nalezena.');}
  $leader=(int)($in['leader_trainer_id']??0);clubExpensePerson($p,'trainer',$leader,'Vedoucí',false);
