 });
}
function clubExpenseSum(PDO $p,string $sql,array $params):int {$q=$p->prepare($sql);$q->execute($params);return (int)$q->fetchColumn();}
function clubExpenseHistoricalPaid(PDO $p,int $root):int {
 $q=$p->prepare("SELECT movement_id,amount_minor FROM accounting_allocations WHERE case_type='expense_claim' AND case_id=? ORDER BY id");$q->execute([$root]);$current=[];$peak=[];foreach($q->fetchAll(PDO::FETCH_ASSOC) as $a){$m=(int)$a['movement_id'];$current[$m]=($current[$m]??0)+(int)$a['amount_minor'];$peak[$m]=max($peak[$m]??0,$current[$m]);}return array_sum($peak);
}
function clubExpenseClaimBalance(PDO $p,int $root,?string $asOf=null):array {
 $q=$p->prepare('SELECT * FROM club_expense_claims WHERE root_id=? ORDER BY version_no DESC');$q->execute([$root]);$rows=$q->fetchAll(PDO::FETCH_ASSOC);$active=null;foreach($rows as $r)if($asOf===null?$r['state']==='approved':($r['approved_at']!==null&&substr($r['approved_at'],0,10)<=clubExpenseDate($asOf))){$active=$r;break;}
 $dateSql=$asOf===null?'':' AND effective_on<=?';$args=$asOf===null?[$root]:[$root,$asOf];
 $paid=clubExpenseSum($p,"SELECT COALESCE(SUM(amount_minor),0) FROM accounting_allocations WHERE case_type='expense_claim' AND case_id=?".$dateSql,$args);
 $consumed=clubExpenseSum($p,'SELECT COALESCE(SUM(amount_minor),0) FROM club_expense_consumptions WHERE claim_root_id=?'.$dateSql,$args);
 $returned=clubExpenseSum($p,"SELECT COALESCE(SUM(amount_minor),0) FROM accounting_allocations WHERE case_type='expense_claim_return' AND case_id=?".$dateSql,$args);
 return ['approved_minor'=>(int)($active['accepted_minor']??0),'paid_minor'=>$paid,'returned_minor'=>$returned,'net_paid_minor'=>$paid-$returned,'consumed_minor'=>$consumed,'remaining_minor'=>(int)($active['accepted_minor']??0)-$paid+$returned-$consumed,'active_claim'=>$active];
}
/** An immutable version includes the exact receipt proof, counterparties and split. */
function clubExpenseCreateClaim(PDO $p,array $in,int $actor,string $reason,bool $confirmed):array {
 return clubExpenseWrite($p,$actor,$reason,$confirmed,function($reason)use($p,$in,$actor){
  $case=(int)($in['case_id']??0);clubExpenseOpenCase($p,$case?:null);$amount=clubExpenseMinor($in['amount_minor']??null);$accepted=0;$sum=0;$items=[];
  foreach($in['items']??[] as $item){$n=clubExpenseMinor($item['amount_minor']??null);$ok=($item['accepted']??null)===true;$itemCase=(int)($item['case_id']??$case);clubExpenseOpenCase($p,$itemCase?:null);$stock=(int)($item['stock_movement_id']??0);if($stock){$q=$p->prepare("SELECT id FROM shop_stock_movements WHERE id=? AND kind='receipt'");$q->execute([$stock]);if(!$q->fetchColumn())throw new ClubExpenseException('Skladová příjemka nebyla nalezena.');}$items[]=['stock_movement_id'=>$stock?:null,'amount_minor'=>$n,'accepted'=>$ok,'case_id'=>$itemCase?:null,'activity'=>accountingLedgerText((string)($item['activity']??''),120),'purpose'=>accountingLedgerText((string)($item['purpose']??''),500)];$sum+=$n;if($ok)$accepted+=$n;}
  if(!$items||$sum!==$amount)throw new ClubExpenseException('Součet uznaných a neuznaných položek musí odpovídat celému dokladu.');
  $fund=(string)($in['funding_source']??'');if(!in_array($fund,['unpaid_supplier','personal','club','advance'],true))throw new ClubExpenseException('Vyberte skutečný zdroj úhrady.');
  $payer=clubExpensePerson($p,(string)($in['payer_kind']??''),(int)($in['payer_id']??0),(string)($in['payer_label']??''));
  $creditor=clubExpensePerson($p,(string)($in['creditor_kind']??''),(int)($in['creditor_id']??0),(string)($in['creditor_label']??''));
  if(in_array($fund,['unpaid_supplier','club'],true)&&$creditor['kind']!=='supplier')throw new ClubExpenseException('Neuhrazená faktura musí mít věřitele dodavatele.');
  if(in_array($fund,['personal','advance'],true)&&($payer['kind']==='supplier'||$payer!==$creditor))throw new ClubExpenseException('Vlastní peníze nebo záloha vyžadují tutéž konkrétní osobu plátce a příjemce.');
  $receipt=(int)($in['receipt_id']??0);$attachment='';$hash='';$proof=accountingLedgerText((string)($in['document_evidence']??''),2000);
  if($receipt){$r=financialReceiptLock($p,$receipt);if(!empty($r['udalost_id'])&&!($in['previous_id']??0))financialEventAssertOpen(financialEventLock($p,(int)$r['udalost_id']));$attachment=(string)($r['obrazek_path']??'');if($attachment!==''){require_once __DIR__.'/private_storage.php';$path=privateStorageResolve($attachment);if(!$path||!is_file($path))throw new ClubExpenseException('Soukromý podklad nelze ověřit.');$hash=hash_file('sha256',$path);}}
  $previous=(int)($in['previous_id']??0);$root=null;$version=1;
  if($previous){$old=clubExpenseOne($p,'club_expense_claims',$previous);$root=(int)$old['root_id'];$version=(int)$old['version_no']+1;$q=$p->prepare('SELECT MAX(version_no) FROM club_expense_claims WHERE root_id=?');$q->execute([$root]);$latestVersion=(int)$q->fetchColumn();if($old['state']==='draft'||$old['state']==='submitted')throw new ClubExpenseException('Nejprve vraťte rozpracovanou verzi k opravě.');if($old['funding_source']!==$fund||$old['creditor_kind']!==$creditor['kind']||(int)$old['creditor_id']!==(int)$creditor['id']||$old['creditor_label']!==$creditor['label'])throw new ClubExpenseException('Oprava nesmí změnit příjemce ani zdroj již vedeného závazku.');}
  $originalCurrency=strtoupper((string)($in['original_currency']??'CZK'));$originalAmount=clubExpenseMinor($in['original_amount_minor']??$amount);$conversion=(string)($in['conversion_evidence']??'');if(!preg_match('/^[A-Z]{3}$/D',$originalCurrency))throw new ClubExpenseException('Neplatná původní měna.');if($originalCurrency!=='CZK')$conversion=accountingLedgerText($conversion,2000);elseif($originalAmount!==$amount)throw new ClubExpenseException('Částka CZK musí souhlasit s originálem.');
  $row=['root_id'=>$root,'version_no'=>$version,'previous_id'=>$previous?:null,'case_id'=>$case?:null,'receipt_id'=>$receipt?:null,'supplier'=>accountingLedgerText((string)($in['supplier']??'')),'document_number'=>accountingLedgerText((string)($in['document_number']??''),120),'document_on'=>accountingLedgerDate((string)($in['document_on']??'')),'due_on'=>clubExpenseDate((string)($in['due_on']??'')),'currency'=>'CZK','amount_minor'=>$amount,'accepted_minor'=>$accepted,'original_currency'=>$originalCurrency,'original_amount_minor'=>$originalAmount,'conversion_evidence'=>$conversion,'funding_source'=>$fund,'payer_kind'=>$payer['kind'],'payer_id'=>$payer['id'],'payer_label'=>$payer['label'],'creditor_kind'=>$creditor['kind'],'creditor_id'=>$creditor['id'],'creditor_label'=>$creditor['label'],'payee_evidence'=>accountingLedgerText((string)($in['payee_evidence']??''),2000),'purpose'=>accountingLedgerText((string)($in['purpose']??''),2000),'document_evidence'=>$proof,'attachment_reference'=>$attachment,'attachment_sha256'=>$hash,'duplicate_review'=>trim((string)($in['duplicate_review']??'')),'items_json'=>json_encode($items,JSON_THROW_ON_ERROR),'created_by'=>$actor,'request_key'=>accountingLedgerText((string)($in['request_key']??''),100)];
  $fingerprint=hash('sha256',json_encode($row,JSON_THROW_ON_ERROR));$q=$p->prepare('SELECT * FROM club_expense_claims WHERE request_key=?');$q->execute([$row['request_key']]);if($prior=$q->fetch(PDO::FETCH_ASSOC)){if(!hash_equals($prior['fingerprint'],$fingerprint))throw new ClubExpenseException('Opakovaný klíč má jiný obsah.');return $prior;}
