  $q=$p->prepare("SELECT id FROM club_expense_claims WHERE (supplier=? AND document_number=? AND document_on=? AND amount_minor=?) OR (attachment_sha256<>'' AND attachment_sha256=?)");$q->execute([$row['supplier'],$row['document_number'],$row['document_on'],$amount,$hash]);$duplicates=$q->fetchAll(PDO::FETCH_COLUMN);if($duplicates&&!$previous&&mb_strlen($row['duplicate_review'])<10)throw new ClubExpenseException('Možná duplicita dokladu #'.implode(', ',$duplicates).'. Nejprve doložte prověření.');
  $row['fingerprint']=$fingerprint;$keys=array_keys($row);$p->prepare('INSERT INTO club_expense_claims('.implode(',',$keys).') VALUES('.implode(',',array_fill(0,count($keys),'?')).')')->execute(array_values($row));$id=(int)$p->lastInsertId();if(!$root)$p->prepare('UPDATE club_expense_claims SET root_id=? WHERE id=?')->execute([$id,$id]);clubExpenseEvent($p,'claim',$id,'created',$actor,$reason,$proof);return clubExpenseOne($p,'club_expense_claims',$id);
 });
}
function clubExpenseClaimTransition(PDO $p,int $id,string $action,int $actor,string $reason,bool $confirmed):array {
 return clubExpenseWrite($p,$actor,$reason,$confirmed,function($reason)use($p,$id,$action,$actor){$r=clubExpenseOne($p,'club_expense_claims',$id);clubExpenseOpenCase($p,$r['case_id']?(int)$r['case_id']:null);
  if($action==='submit'&&$r['state']==='draft'){$state='submitted';$p->prepare('UPDATE club_expense_claims SET submitted_by=? WHERE id=?')->execute([$actor,$id]);}
  elseif(in_array($action,['return','reject','approve'],true)&&$r['state']==='submitted'){
   $state=match($action){'return'=>'returned','reject'=>'rejected',default=>'approved'};
   if($action==='approve'){foreach(json_decode($r['items_json'],true,512,JSON_THROW_ON_ERROR) as $part)clubExpenseOpenCase($p,empty($part['case_id'])?null:(int)$part['case_id']);if((int)$r['created_by']===$actor||(int)$r['submitted_by']===$actor||($r['creditor_kind']==='trainer'&&(int)$r['creditor_id']===$actor))throw new ClubExpenseException('Vlastní výdaj nebo předložení musí schválit jiná pověřená osoba. Výjimka není nastavena.');
    $balance=clubExpenseClaimBalance($p,(int)$r['root_id']);if((int)$r['accepted_minor']<clubExpenseHistoricalPaid($p,(int)$r['root_id'])-$balance['returned_minor']+$balance['consumed_minor']&&clubExpenseHistoricalPaid($p,(int)$r['root_id'])>$balance['paid_minor'])throw new ClubExpenseException('Nejprve opravte uvolněné příděly výplaty. Uvolnění není skutečné vrácení peněz a nesmí skrýt pohledávku.');if((int)$r['accepted_minor']<$balance['consumed_minor'])throw new ClubExpenseException('Nejprve opravte čerpání zálohy tak, aby odpovídalo uznané částce.');
    $p->prepare("UPDATE club_expense_claims SET state='superseded' WHERE root_id=? AND state='approved'")->execute([$r['root_id']]);$p->prepare('UPDATE club_expense_claims SET approved_by=?,approved_at=CURRENT_TIMESTAMP WHERE id=?')->execute([$actor,$id]);
   }
  }else throw new ClubExpenseException('Neplatný přechod nebo již rozhodnutá verze.');
  $p->prepare('UPDATE club_expense_claims SET state=? WHERE id=?')->execute([$state,$id]);clubExpenseEvent($p,'claim',$id,$action,$actor,$reason);return clubExpenseOne($p,'club_expense_claims',$id);
 });
}
function clubExpenseCreateAdvance(PDO $p,array $in,int $actor,string $reason,bool $confirmed):array {
 return clubExpenseWrite($p,$actor,$reason,$confirmed,function($reason)use($p,$in,$actor){$case=(int)($in['case_id']??0);if(!$case)throw new ClubExpenseException('Záloha vyžaduje finanční případ.');clubExpenseOpenCase($p,$case);$person=clubExpensePerson($p,(string)($in['recipient_kind']??''),(int)($in['recipient_id']??0),(string)($in['recipient_label']??''),false);
 $row=['case_id'=>$case,'recipient_kind'=>$person['kind'],'recipient_id'=>$person['id'],'recipient_label'=>$person['label'],'payee_evidence'=>accountingLedgerText((string)($in['payee_evidence']??''),2000),'currency'=>'CZK','limit_minor'=>clubExpenseMinor($in['limit_minor']??null),'due_on'=>clubExpenseDate((string)($in['due_on']??'')),'purpose'=>accountingLedgerText((string)($in['purpose']??''),2000),'created_by'=>$actor,'request_key'=>accountingLedgerText((string)($in['request_key']??''),100)];$fp=hash('sha256',json_encode($row,JSON_THROW_ON_ERROR));$q=$p->prepare('SELECT * FROM club_expense_advances WHERE request_key=?');$q->execute([$row['request_key']]);if($old=$q->fetch(PDO::FETCH_ASSOC)){if(!hash_equals($fp,$old['fingerprint']))throw new ClubExpenseException('Záloha již má jiný obsah.');return $old;}$row['fingerprint']=$fp;$keys=array_keys($row);$p->prepare('INSERT INTO club_expense_advances('.implode(',',$keys).') VALUES('.implode(',',array_fill(0,count($keys),'?')).')')->execute(array_values($row));$id=(int)$p->lastInsertId();clubExpenseEvent($p,'advance',$id,'requested',$actor,$reason);return clubExpenseOne($p,'club_expense_advances',$id);});
}
function clubExpenseAdvanceBalance(PDO $p,int $id,?string $asOf=null):array {
 $dateSql=$asOf===null?'':' AND effective_on<=?';$args=$asOf===null?[$id]:[$id,clubExpenseDate($asOf)];
 $out=clubExpenseSum($p,"SELECT COALESCE(SUM(amount_minor),0) FROM accounting_allocations WHERE case_type='expense_advance_out' AND case_id=?".$dateSql,$args);$in=clubExpenseSum($p,"SELECT COALESCE(SUM(amount_minor),0) FROM accounting_allocations WHERE case_type='expense_advance_in' AND case_id=?".$dateSql,$args);$used=clubExpenseSum($p,'SELECT COALESCE(SUM(amount_minor),0) FROM club_expense_consumptions WHERE advance_id=?'.$dateSql,$args);$transferred=clubExpenseSum($p,'SELECT COALESCE(SUM(amount_minor),0) FROM club_expense_transfers WHERE to_advance_id=?'.$dateSql,$args)-clubExpenseSum($p,'SELECT COALESCE(SUM(amount_minor),0) FROM club_expense_transfers WHERE from_advance_id=?'.$dateSql,$args);
 return ['out_minor'=>$out,'returned_minor'=>$in,'consumed_minor'=>$used,'transferred_minor'=>$transferred,'balance_minor'=>$out+$transferred-$used-$in];
}
function clubExpenseAdvanceTransition(PDO $p,int $id,string $action,int $actor,string $reason,bool $confirmed):array {
 return clubExpenseWrite($p,$actor,$reason,$confirmed,function($reason)use($p,$id,$action,$actor){$a=clubExpenseOne($p,'club_expense_advances',$id);clubExpenseOpenCase($p,(int)$a['case_id']);
 if($action==='approve'&&$a['state']==='requested'){if((int)$a['created_by']===$actor||($a['recipient_kind']==='trainer'&&(int)$a['recipient_id']===$actor))throw new ClubExpenseException('Vlastní zálohu musí schválit jiná pověřená osoba.');$p->prepare("UPDATE club_expense_advances SET state='approved',approved_by=? WHERE id=?")->execute([$actor,$id]);}
 elseif($action==='close'&&$a['state']==='approved'){if(clubExpenseAdvanceBalance($p,$id)['balance_minor']!==0)throw new ClubExpenseException('Záloha není vypořádaná; doložte vratku nebo doplatek.');$p->prepare("UPDATE club_expense_advances SET state='closed' WHERE id=?")->execute([$id]);}else throw new ClubExpenseException('Neplatný stav zálohy.');clubExpenseEvent($p,'advance',$id,$action,$actor,$reason);return clubExpenseOne($p,'club_expense_advances',$id);});
}
/** Called by the canonical ledger as well as this UI, preventing direct generic allocation bypass. */
function clubExpenseValidateAllocation(PDO $p,array $m,string $type,int $id,int $amount,?int $reverses):void {
 if(in_array($type,['expense_claim','expense_claim_return'],true)){$b=clubExpenseClaimBalance($p,$id);$r=$b['active_claim'];if(!$r)throw new ClubExpenseException('Výdaj nemá schválenou verzi.');clubExpenseOpenCase($p,$r['case_id']?(int)$r['case_id']:null);foreach(json_decode($r['items_json'],true,512,JSON_THROW_ON_ERROR) as $part)clubExpenseOpenCase($p,empty($part['case_id'])?null:(int)$part['case_id']);if($r['funding_source']==='advance')throw new ClubExpenseException('Čerpání zálohy nevytváří druhý peněžní výdaj.');
 if($type==='expense_claim_return'){if((int)$m['amount_minor']<=0||$m['kind']!=='income')throw new ClubExpenseException('Vrácení přeplatku vyžaduje skutečný příjem.');if($amount>0&&$amount>max(0,-$b['remaining_minor']))throw new ClubExpenseException('Vrácení přesahuje doložený přeplatek výdaje.');}
 else{if((int)$m['amount_minor']>=0||$m['kind']!=='expense')throw new ClubExpenseException('Proplacení vyžaduje skutečný výdaj.');if($amount>0&&$amount>$b['remaining_minor'])throw new ClubExpenseException('Proplacení přesahuje zbývající závazek.');if($amount<0&&($b['remaining_minor']<0||$b['returned_minor']>0))throw new ClubExpenseException('Výplatu s pohledávkou nebo vratkou nelze uvolnit; použijte doložený příjem vratky.');}}
 else{$a=clubExpenseOne($p,'club_expense_advances',$id);clubExpenseOpenCase($p,(int)$a['case_id']);if($a['state']!=='approved')throw new ClubExpenseException('Záloha není schválená nebo je již uzavřená.');$b=clubExpenseAdvanceBalance($p,$id);
 if($type==='expense_advance_out'){if((int)$m['amount_minor']>=0||$m['kind']!=='expense')throw new ClubExpenseException('Předání vyžaduje skutečný výdaj.');if($amount>0&&$b['out_minor']+$amount>(int)$a['limit_minor'])throw new ClubExpenseException('Předání překračuje schválenou zálohu.');if($amount<0&&$b['balance_minor']+$amount<0)throw new ClubExpenseException('Nelze uvolnit již spotřebovanou zálohu.');}
 elseif($type==='expense_advance_in'){if((int)$m['amount_minor']<=0||$m['kind']!=='income')throw new ClubExpenseException('Vrácení vyžaduje skutečný příjem.');if($amount>0&&$amount>$b['balance_minor'])throw new ClubExpenseException('Vratka přesahuje nevypořádanou zálohu.');}else throw new ClubExpenseException('Neplatný druh přídělu.');}
}
function clubExpenseAllocate(PDO $p,string $type,int $id,int $movement,int $amount,string $key,string $date,int $actor,string $reason,bool $confirmed,?int $reverses=null):array {
 if(!in_array($type,['expense_claim','expense_claim_return','expense_advance_out','expense_advance_in'],true))throw new ClubExpenseException('Neplatný druh vypořádání.');return accountingLedgerAllocate($p,$movement,$type,$id,$amount,$key,$actor,$reason,$confirmed,$reverses,'','',$date);
}
function clubExpenseConsume(PDO $p,int $root,int $advance,int $amount,string $key,string $date,int $actor,string $reason,bool $confirmed,?int $reverses=null):array {
