}
function clubExpenseExportRows(PDO $p,string $from,string $to):array {
 clubExpenseDate($from);clubExpenseDate($to);if($from>$to)throw new ClubExpenseException('Neplatné období exportu.');$opening=(new DateTimeImmutable($from))->modify('-1 day')->format('Y-m-d');$result=[];
 $q=$p->prepare('SELECT * FROM club_expense_claims WHERE document_on<=? AND created_at<? ORDER BY root_id,version_no');$q->execute([$to,$to.' 23:59:59']);$result['claims']=$q->fetchAll(PDO::FETCH_ASSOC);
 foreach($result['claims'] as &$r){$b=clubExpenseClaimBalance($p,(int)$r['root_id'],$to);$o=clubExpenseClaimBalance($p,(int)$r['root_id'],$opening);$r['state_current']=$r['state'];$r['is_effective_approval']=$b['active_claim']!==null&&(int)$b['active_claim']['id']===(int)$r['id'];$q=$p->prepare("SELECT event_type FROM club_expense_events WHERE entity_type='claim' AND entity_id=? AND created_at<=? ORDER BY id DESC LIMIT 1");$q->execute([$r['id'],$to.' 23:59:59']);$event=$q->fetchColumn();$r['state']=$r['is_effective_approval']?'approved':match($event){'submit'=>'submitted','return'=>'returned','reject'=>'rejected','created'=>'draft',default=>'historical'};$r['paid_minor']=$b['paid_minor'];$r['returned_minor']=$b['returned_minor'];$r['net_paid_minor']=$b['net_paid_minor'];$r['consumed_minor']=$b['consumed_minor'];$r['remaining_minor']=$r['is_effective_approval']?$b['remaining_minor']:0;$r['opening_remaining_minor']=$r['is_effective_approval']?$o['remaining_minor']:0;}unset($r);
 $q=$p->prepare('SELECT * FROM club_expense_advances WHERE created_at<? ORDER BY id');$q->execute([$to.' 23:59:59']);$result['advances']=$q->fetchAll(PDO::FETCH_ASSOC);foreach($result['advances'] as &$r){$r+=clubExpenseAdvanceBalance($p,(int)$r['id'],$to);$r['opening_balance_minor']=clubExpenseAdvanceBalance($p,(int)$r['id'],$opening)['balance_minor'];}unset($r);
 $q=$p->prepare("SELECT a.*,m.effective_on AS movement_on,m.amount_minor AS movement_minor,m.evidence AS movement_evidence FROM accounting_allocations a JOIN accounting_movements m ON m.id=a.movement_id WHERE a.case_type IN ('expense_claim','expense_claim_return','expense_advance_out','expense_advance_in') AND a.effective_on<=? ORDER BY a.id");$q->execute([$to]);$result['allocations']=$q->fetchAll(PDO::FETCH_ASSOC);
 foreach(['consumptions','transfers'] as $type){$q=$p->prepare('SELECT * FROM club_expense_'.$type.' WHERE effective_on<=? ORDER BY id');$q->execute([$to]);$result[$type]=$q->fetchAll(PDO::FETCH_ASSOC);}
 foreach(['events','cases'] as $type){$q=$p->prepare('SELECT * FROM club_expense_'.$type.' WHERE created_at<? ORDER BY id');$q->execute([$to.' 23:59:59']);$result[$type]=$q->fetchAll(PDO::FETCH_ASSOC);}return $result;
}
